-- TRIT 162 Artikel: Rechnungs- und Gutschriftzeilen ab 2025 mit/ohne Wareneingang am oder vor Belegdatum, Lieferant des letzten WE
SELECT x."WE", x."VC", COUNT(*) AS ZEILEN, SUM(x."LT") AS EUR FROM (
 SELECT p."ItemCode", p."LineTotal" AS "LT",
  CASE WHEN w."vc" IS NULL THEN 'ohne WE' ELSE 'mit WE' END AS "WE", COALESCE(w."vc", '-') AS "VC"
 FROM "{SCHEMA}"."OINV" h INNER JOIN "{SCHEMA}"."INV1" p ON p."DocEntry" = h."DocEntry"
 LEFT JOIN (
  SELECT y."de", y."ln", y."vc" FROM (
   SELECT p2."DocEntry" AS "de", p2."LineNum" AS "ln", o2."CardCode" AS "vc",
     ROW_NUMBER() OVER (PARTITION BY p2."DocEntry", p2."LineNum" ORDER BY o2."DocDate" DESC, o2."DocEntry" DESC) AS "rn"
   FROM "{SCHEMA}"."OINV" h2 INNER JOIN "{SCHEMA}"."INV1" p2 ON p2."DocEntry" = h2."DocEntry"
   INNER JOIN "{SCHEMA}"."PDN1" g2 ON g2."ItemCode" = p2."ItemCode" AND g2."Quantity" > 0
   INNER JOIN "{SCHEMA}"."OPDN" o2 ON o2."DocEntry" = g2."DocEntry" AND o2."CANCELED" = 'N' AND o2."DocDate" <= h2."DocDate"
   WHERE h2."CANCELED" = 'N' AND h2."DocDate" >= '2025-01-01' AND UPPER(p2."ItemCode") IN ('53726','53727','53765','53768','53770','53878','53983','54056','54290','54364','55163','55164','55378','55711','56060','57203','57382','57544','57930','58002','58082','58136','58138','58189','58267','58268','58269','58286','58454','58478','58541','58682','58909','58910','59239','59242','59392','59964','60056','60128','60129','60283','60284','60286','60287','60288','60402','60468','60469','60470','60471','60472','60474','60475','60557','60558','60872','60900','60904','61498','61905','62109','62165','62166','62167','62168','62366','62369','62550','62918','62919','62920','62929','63017','63098','63179','63376','63441','63598','63601','63602','63603','63724','63957','64176','64953','64954','65137','65140','65141','65143','65163','65198','65392','65452','65683','65733','65872','65951','65997','66015','66176','66187','66234','66259','67496','GC10603','GC10636','GC10745','GC10814','GC10817','GC11032','GC11080','GC11402','GC11533','GC11794','GC11802','GC11821','GC11844','GC11887','GC11890','GC11902','GC11903','GC11904','GC11905','GC11906','GC11907','GC11908','GC11909','GC11910','GC11911','GC11912','GC11913','GC11914','GC11916','GC11917','GC11918','GC11919','GC11921','GC11924','GC11925','GC11927','GC11928','GC11929','GC11930','GC11931','GC11932','GC11933','GC11940','GC11941','GC11942','GC11943','GC11944','GC11945','GC11949','M_IT01_000311','M_IT01_000320','M_IT01_000531','M_IT01_000760','M_IT01_000842','M_IT01_001778','M_IT01_005751')
  ) y WHERE y."rn" = 1
 ) w ON w."de" = p."DocEntry" AND w."ln" = p."LineNum"
 WHERE h."CANCELED" = 'N' AND h."DocDate" >= '2025-01-01' AND UPPER(p."ItemCode") IN ('53726','53727','53765','53768','53770','53878','53983','54056','54290','54364','55163','55164','55378','55711','56060','57203','57382','57544','57930','58002','58082','58136','58138','58189','58267','58268','58269','58286','58454','58478','58541','58682','58909','58910','59239','59242','59392','59964','60056','60128','60129','60283','60284','60286','60287','60288','60402','60468','60469','60470','60471','60472','60474','60475','60557','60558','60872','60900','60904','61498','61905','62109','62165','62166','62167','62168','62366','62369','62550','62918','62919','62920','62929','63017','63098','63179','63376','63441','63598','63601','63602','63603','63724','63957','64176','64953','64954','65137','65140','65141','65143','65163','65198','65392','65452','65683','65733','65872','65951','65997','66015','66176','66187','66234','66259','67496','GC10603','GC10636','GC10745','GC10814','GC10817','GC11032','GC11080','GC11402','GC11533','GC11794','GC11802','GC11821','GC11844','GC11887','GC11890','GC11902','GC11903','GC11904','GC11905','GC11906','GC11907','GC11908','GC11909','GC11910','GC11911','GC11912','GC11913','GC11914','GC11916','GC11917','GC11918','GC11919','GC11921','GC11924','GC11925','GC11927','GC11928','GC11929','GC11930','GC11931','GC11932','GC11933','GC11940','GC11941','GC11942','GC11943','GC11944','GC11945','GC11949','M_IT01_000311','M_IT01_000320','M_IT01_000531','M_IT01_000760','M_IT01_000842','M_IT01_001778','M_IT01_005751')
) x GROUP BY x."WE", x."VC" ORDER BY 3 DESC
